pub fn tv_list_locked(l: [*c]const list_T) callconv(.c) VarLockStatus {
    _ = &l;
    if (l == @as([*c]const list_T, @ptrCast(@alignCast(@as(?*anyopaque, @ptrFromInt(@as(c_int, 0))))))) {
        return @as(c_uint, @bitCast(VAR_FIXED));
