pub fn tv_list_set_lock(l: [*c]list_T, lock: VarLockStatus) callconv(.c) void {
    _ = &l;
    _ = &lock;
    if (l == @as([*c]list_T, @ptrCast(@alignCast(@as(?*anyopaque, @ptrFromInt(@as(c_int, 0))))))) {
        _ = blk: {
            _ = @sizeOf(c_int);
            break :blk blk_1: {
                break :blk_1 if (lock == @as(c_uint, @bitCast(VAR_FIXED))) {} else {
                    __assert_fail("lock == VAR_FIXED", "src/nvim/eval/typval.h", @as(c_uint, @bitCast(@as(c_int, 76))), "void tv_list_set_lock(list_T *const, const VarLockStatus)");
                };
            };
        };
        return;
    }
    l.*.lv_lock = lock;
}
