pub inline fn tv_blob_get(b: [*c]const blob_T, arg_idx: c_int) u8 {
    _ = &b;
    var idx = arg_idx;
    _ = &idx;
    return (blk: {
        const tmp = idx;
        if (tmp >= 0) break :blk @as([*c]u8, @ptrCast(@alignCast(b.*.bv_ga.ga_data))) + @as(usize, @intCast(tmp)) else break :blk @as([*c]u8, @ptrCast(@alignCast(b.*.bv_ga.ga_data))) - ~@as(usize, @bitCast(@as(isize, @intCast(tmp)) +% -1));
    }).*;
}
