    _ = &blob;
    var idx = arg_idx;
    _ = &idx;
    var c = arg_c;
    _ = &c;
    (blk: {
        const tmp = idx;
        if (tmp >= 0) break :blk @as([*c]u8, @ptrCast(@alignCast(blob.*.bv_ga.ga_data))) + @as(usize, @intCast(tmp)) else break :blk @as([*c]u8, @ptrCast(@alignCast(blob.*.bv_ga.ga_data))) - ~@as(usize, @bitCast(@as(isize, @intCast(tmp)) +% -1));
    }).* = c;
}
