pub fn tv_get_float_chk(tv: [*c]const typval_T, ret_f: [*c]float_T) callconv(.c) bool {
    _ = &tv;
    _ = &ret_f;
    if (tv.*.v_type == @as(c_uint, @bitCast(VAR_FLOAT))) {
        ret_f.* = tv.*.vval.v_float;
        return @as(c_int, 1) != 0;
    }
    if (tv.*.v_type == @as(c_uint, @bitCast(VAR_NUMBER))) {
        ret_f.* = @as(float_T, @floatFromInt(tv.*.vval.v_number));
        return @as(c_int, 1) != 0;
    }
    _ = semsg("%s", gettext("E808: Number or Float required"));
    return @as(c_int, 0) != 0;
}
