pub fn win_hl_attr(arg_wp: [*c]win_T, arg_hlf: c_int) callconv(.c) c_int {
    var wp = arg_wp;
    _ = &wp;
    var hlf = arg_hlf;
    _ = &hlf;
    return (blk: {
        const tmp = hlf;
        if (tmp >= 0) break :blk (if ((wp.*.w_ns_hl_attr != null) and (ns_hl_fast < @as(c_int, 0))) wp.*.w_ns_hl_attr else hl_attr_active) + @as(usize, @intCast(tmp)) else break :blk (if ((wp.*.w_ns_hl_attr != null) and (ns_hl_fast < @as(c_int, 0))) wp.*.w_ns_hl_attr else hl_attr_active) - ~@as(usize, @bitCast(@as(isize, @intCast(tmp)) +% -1));
    }).*;
}
