pub inline fn strappend(dst: [*c]u8, src: [*c]const u8) [*c]u8 {
    _ = &dst;
    _ = &src;
    const src_len: usize = strlen(src);
    _ = &src_len;
    return @as([*c]u8, @ptrCast(@alignCast(memmove(@as(?*anyopaque, @ptrCast(dst)), @as(?*const anyopaque, @ptrCast(src)), src_len)))) + src_len;
}
pub const terminal_write_cb = ?*const fn ([*c]const u8, usize, ?*anyopaque) callconv(.c) void;
